// Shrink each call's AI data down to the fields we actually need for analysis,
// then aggregate everything into a single item so the AI Agent runs once.
const items = $input.all();

const pick = (obj, keys) => {
  for (const k of keys) {
    if (obj && obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return undefined;
};

const compact = [];
for (const i of items) {
  const c = i.json || {};
  // Skip calls where NUACOM had no AI data (404 continued as an error item)
  if (c.error || Object.keys(c).length === 0) continue;
  const ai = c.ai || c.analysis || c.ai_data || {};
  const entry = {
    id: pick(c, ['id', 'call_id', 'callId']),
    date: pick(c, ['date', 'datetime', 'created_at', 'time', 'call_date']),
    direction: pick(c, ['direction', 'type']),
    from: pick(c, ['from', 'src', 'caller', 'source']),
    to: pick(c, ['to', 'dst', 'callee', 'destination']),
    agent: pick(c, ['agent', 'agent_name', 'extension', 'ext']),
    duration: pick(c, ['duration', 'talk_time', 'billsec']),
    summary: pick(c, ['summary', 'ai_summary']) ?? pick(ai, ['summary']),
    sentiment: pick(c, ['sentiment']) ?? pick(ai, ['sentiment']),
    topics: pick(c, ['topics', 'keywords', 'tags']) ?? pick(ai, ['topics', 'keywords']),
    transcription:
      pick(c, ['transcription', 'transcript', 'text']) ??
      pick(ai, ['transcription', 'transcript', 'text']),
  };
  // Drop empty keys to keep the payload small
  Object.keys(entry).forEach((k) => entry[k] === undefined && delete entry[k]);
  compact.push(entry);
}

return [
  {
    json: {
      count: compact.length,
      periodFrom: $now.startOf('week').minus({ weeks: 1 }).toFormat('yyyy-MM-dd'),
      periodTo: $now.startOf('week').minus({ days: 1 }).toFormat('yyyy-MM-dd'),
      calls: compact,
    },
  },
];

